import re
import shutil
import subprocess
import time
from pathlib import Path
RUNNER_WORKSPACES_ROOT = Path('/var/lib/ci-runners/workspaces')
REPORT_ARCHIVE_ROOT = Path('/var/lib/ci-runners/archived-reports')

def _archive_test_reports(workspace: Path, runner_id: str):
    # Preserve the previous job's test reports by moving them out of the checkout before cleaning.
    reports = workspace / 'test-reports'
    if not reports.is_dir():
        return None
    dest = REPORT_ARCHIVE_ROOT / runner_id / time.strftime('%Y%m%d-%H%M%S')
    dest.parent.mkdir(parents=True, exist_ok=True)
    shutil.move(str(reports), str(dest))
    return str(dest)

def clean_runner_workspace(runner_id: str, include_ignored: bool=False) -> dict:
    if not runner_id or not re.fullmatch('[A-Za-z0-9_.-]+', runner_id):
        return {'ok': False, 'error': 'runner_id must be alphanumeric with dashes, dots or underscores'}
    workspace = RUNNER_WORKSPACES_ROOT / runner_id
    if not workspace.is_dir():
        return {'ok': False, 'error': f'no workspace found for runner {runner_id}'}
    if not (workspace / '.git').exists():
        return {'ok': False, 'error': f'workspace for {runner_id} is not a git checkout'}
    archived_reports = _archive_test_reports(workspace, runner_id)
    clean_flags = '-fdx' if include_ignored else '-fd'
    commands = [['git', 'reset', '--hard', 'HEAD'], ['git', 'clean', clean_flags]]
    outputs = []
    for command in commands:
        result = subprocess.run(command, cwd=workspace, capture_output=True, text=True, timeout=300)
        if result.returncode != 0:
            return {'ok': False, 'error': result.stderr.strip(), 'command': ' '.join(command)}
        outputs.append(result.stdout.strip())
    removed = [line for line in outputs[1].splitlines() if line.startswith('Removing ')]
    return {'ok': True, 'runner_id': runner_id, 'removed_count': len(removed), 'removed': removed[:200], 'archived_reports': archived_reports}
